/* Generated by AGRr!. Applies the saved theme before the page first paints. */
/* Persistence key: "agrrr:theme" in localStorage, holding a theme id. */
(function () {
  'use strict';
  var KEY = 'agrrr:theme';
  var DEFAULT_THEME = 'dark';
  var THEMES = ['dark', 'light'];
  var stored = null;
  try {
    stored = window.localStorage.getItem(KEY);
  } catch (error) {
    stored = null;
  }
  var theme = stored !== null && THEMES.indexOf(stored) !== -1 ? stored : null;
  if (theme === null) {
    var prefersDark = false;
    try {
      prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    } catch (error) {
      prefersDark = false;
    }
    if (prefersDark) {
      theme = 'dark';
    }
  }
  document.documentElement.setAttribute('data-theme', theme === null ? DEFAULT_THEME : theme);
})();
